import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiUser, FiPhone, FiLock, FiSave, FiEdit2, FiX, FiPackage, FiCalendar } from 'react-icons/fi';

const Profile = () => {
    const { user, logout } = useAuth();
    const [loading, setLoading] = useState(false);
    const [editMode, setEditMode] = useState(false);
    const [userStats, setUserStats] = useState({ totalProducts: 0, createdAt: '' });
    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [error, setError] = useState('');

    useEffect(() => {
        if (user) {
            setFormData({
                name: user.name,
                phone: user.phone,
                currentPassword: '',
                newPassword: '',
                confirmPassword: ''
            });
            fetchUserStats();
        }
    }, [user]);

    const fetchUserStats = async () => {
        try {
            if (user?.type === 'vendedor') {
                const response = await api.get(`/products/seller/${user.id}`);
                if (response.data.success) {
                    setUserStats({
                        totalProducts: response.data.products.length,
                        createdAt: user.createdAt
                    });
                }
            } else {
                setUserStats({
                    totalProducts: 0,
                    createdAt: user.createdAt
                });
            }
        } catch (error) {
            console.error('Erro ao buscar estatísticas:', error);
        }
    };

    const validateAngolaPhone = (phone) => {
        const cleanPhone = phone.replace(/\D/g, '');
        if (cleanPhone.length === 9 && cleanPhone.startsWith('9')) return true;
        if (cleanPhone.length === 12 && cleanPhone.startsWith('2449')) return true;
        return false;
    };

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError('');
    };

    const handlePhoneChange = (e) => {
        let value = e.target.value.replace(/\D/g, '');
        if (value.length > 9) value = value.slice(0, 9);
        setFormData({ ...formData, phone: value });
    };

    const handleSave = async () => {
        setError('');
        
        if (formData.name.length < 3) {
            setError('Nome deve ter pelo menos 3 caracteres');
            return;
        }
        
        if (formData.phone !== user?.phone && !validateAngolaPhone(formData.phone)) {
            setError('Número de telefone inválido');
            return;
        }
        
        if (formData.newPassword) {
            if (formData.newPassword.length < 6) {
                setError('A nova senha deve ter pelo menos 6 caracteres');
                return;
            }
            if (formData.newPassword !== formData.confirmPassword) {
                setError('As novas senhas não coincidem');
                return;
            }
            if (!formData.currentPassword) {
                setError('Digite sua senha atual');
                return;
            }
        }
        
        setLoading(true);
        
        try {
            const updateData = {
                name: formData.name,
                phone: formData.phone
            };
            
            if (formData.newPassword) {
                updateData.currentPassword = formData.currentPassword;
                updateData.newPassword = formData.newPassword;
            }
            
            const response = await api.put('/auth/profile', updateData);
            
            if (response.data.success) {
                toast.success('Perfil atualizado!');
                user.name = formData.name;
                user.phone = formData.phone;
                localStorage.setItem('techmarket_user', JSON.stringify(user));
                setEditMode(false);
                setFormData({
                    name: formData.name,
                    phone: formData.phone,
                    currentPassword: '',
                    newPassword: '',
                    confirmPassword: ''
                });
            }
        } catch (error) {
            toast.error(error.response?.data?.error || 'Erro ao atualizar');
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = () => {
        setFormData({
            name: user?.name || '',
            phone: user?.phone || '',
            currentPassword: '',
            newPassword: '',
            confirmPassword: ''
        });
        setEditMode(false);
        setError('');
    };

    const formatDate = (dateString) => {
        if (!dateString) return 'Data não disponível';
        const date = new Date(dateString);
        return date.toLocaleDateString('pt-BR', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        });
    };

    if (!user) return null;

    return (
        <div className="max-w-lg mx-auto">
            <div className="bg-white rounded-xl shadow-sm overflow-hidden">
                {/* Cabeçalho minimalista */}
                <div className="border-b border-gray-100 px-6 py-4">
                    <div className="flex items-center justify-between">
                        <h1 className="text-lg font-medium text-gray-800">Perfil</h1>
                        {!editMode && (
                            <button
                                onClick={() => setEditMode(true)}
                                className="text-gray-400 hover:text-gray-600 transition text-sm flex items-center gap-1"
                            >
                                <FiEdit2 size={14} />
                                <span>Editar</span>
                            </button>
                        )}
                    </div>
                </div>
                
                <div className="p-6">
                    {error && (
                        <div className="bg-red-50 text-red-500 text-sm p-3 rounded-lg mb-4">
                            {error}
                        </div>
                    )}
                    
                    <div className="space-y-4">
                        {/* Nome */}
                        <div>
                            <label className="block text-xs text-gray-400 mb-1 uppercase tracking-wide">
                                <FiUser className="inline mr-1" size={12} /> Nome
                            </label>
                            {editMode ? (
                                <input
                                    type="text"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleChange}
                                    className="w-full px-0 py-1 border-b border-gray-200 focus:outline-none focus:border-gray-400 text-gray-700"
                                />
                            ) : (
                                <div className="text-gray-700 py-1">{user.name}</div>
                            )}
                        </div>
                        
                        {/* Telefone */}
                        <div>
                            <label className="block text-xs text-gray-400 mb-1 uppercase tracking-wide">
                                <FiPhone className="inline mr-1" size={12} /> Telefone
                            </label>
                            {editMode ? (
                                <div>
                                    <input
                                        type="tel"
                                        name="phone"
                                        value={formData.phone}
                                        onChange={handlePhoneChange}
                                        className="w-full px-0 py-1 border-b border-gray-200 focus:outline-none focus:border-gray-400 text-gray-700"
                                        placeholder="923456789"
                                    />
                                    <p className="text-xs text-gray-400 mt-1">Apenas números</p>
                                </div>
                            ) : (
                                <div className="text-gray-700 py-1">{user.phone}</div>
                            )}
                        </div>
                        
                        {/* Tipo de conta */}
                        <div>
                            <label className="block text-xs text-gray-400 mb-1 uppercase tracking-wide">
                                Tipo de conta
                            </label>
                            <div className="text-gray-700 py-1">
                                {user.type === 'vendedor' ? 'Vendedor' : 'Comprador'}
                            </div>
                        </div>
                        
                        {/* Informações específicas - layout minimalista */}
                        <div className="border-t border-gray-100 pt-4 mt-2 space-y-3">
                            {user.type === 'vendedor' && (
                                <div>
                                    <label className="block text-xs text-gray-400 mb-1 uppercase tracking-wide">
                                        <FiPackage className="inline mr-1" size={12} /> Anúncios
                                    </label>
                                    <div className="text-gray-700 py-1">
                                        {userStats.totalProducts} {userStats.totalProducts === 1 ? 'anúncio' : 'anúncios'}
                                    </div>
                                </div>
                            )}
                            
                            <div>
                                <label className="block text-xs text-gray-400 mb-1 uppercase tracking-wide">
                                    <FiCalendar className="inline mr-1" size={12} /> Membro desde
                                </label>
                                <div className="text-gray-700 py-1">
                                    {formatDate(userStats.createdAt || user.createdAt)}
                                </div>
                            </div>
                        </div>
                        
                        {/* Alterar senha - modo edição */}
                        {editMode && (
                            <div className="border-t border-gray-100 pt-4 mt-2">
                                <h3 className="text-sm font-medium text-gray-600 mb-3">Alterar senha</h3>
                                <div className="space-y-3">
                                    <div>
                                        <label className="block text-xs text-gray-400 mb-1">Senha atual</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-0 top-1/2 transform -translate-y-1/2 text-gray-300" size={14} />
                                            <input
                                                type="password"
                                                name="currentPassword"
                                                value={formData.currentPassword}
                                                onChange={handleChange}
                                                placeholder="Digite sua senha"
                                                className="w-full pl-5 pr-3 py-1 border-b border-gray-200 focus:outline-none focus:border-gray-400 text-sm"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs text-gray-400 mb-1">Nova senha</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-0 top-1/2 transform -translate-y-1/2 text-gray-300" size={14} />
                                            <input
                                                type="password"
                                                name="newPassword"
                                                value={formData.newPassword}
                                                onChange={handleChange}
                                                placeholder="Mínimo 6 caracteres"
                                                className="w-full pl-5 pr-3 py-1 border-b border-gray-200 focus:outline-none focus:border-gray-400 text-sm"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs text-gray-400 mb-1">Confirmar nova senha</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-0 top-1/2 transform -translate-y-1/2 text-gray-300" size={14} />
                                            <input
                                                type="password"
                                                name="confirmPassword"
                                                value={formData.confirmPassword}
                                                onChange={handleChange}
                                                placeholder="Digite novamente"
                                                className="w-full pl-5 pr-3 py-1 border-b border-gray-200 focus:outline-none focus:border-gray-400 text-sm"
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                        
                        {/* Botões - minimalistas */}
                        {editMode && (
                            <div className="flex gap-3 pt-4">
                                <button
                                    onClick={handleSave}
                                    disabled={loading}
                                    className="flex-1 bg-gray-900 text-white py-2 rounded-lg text-sm hover:bg-gray-800 transition flex items-center justify-center gap-2"
                                >
                                    <FiSave size={14} />
                                    {loading ? 'Salvando...' : 'Salvar'}
                                </button>
                                <button
                                    onClick={handleCancel}
                                    className="flex-1 bg-gray-100 text-gray-600 py-2 rounded-lg text-sm hover:bg-gray-200 transition flex items-center justify-center gap-2"
                                >
                                    <FiX size={14} />
                                    Cancelar
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Profile;
